# ! [doc = " From the NLL RFC:"] # ! [doc = " \"Shallow prefixes are found by stripping away fields, but stop at"] # ! [doc = " any dereference. So: writing a path like `a` is illegal if `a.b`"] # ! [doc = " is borrowed. But: writing `a` is legal if `*a` is borrowed,"] # ! [doc = " whether or not `a` is a shared or mutable reference. [...] \""] use split_decls_genesis :: ourprelude :: * ; use rustc_middle :: mir :: { PlaceRef , ProjectionElem } ; use super :: MirBorrowckCtxt ; pub (crate) trait IsPrefixOf < 'tcx > { fn is_prefix_of (& self , other : PlaceRef < 'tcx >) -> bool ; } impl < 'tcx > IsPrefixOf < 'tcx > for PlaceRef < 'tcx > { fn is_prefix_of (& self , other : PlaceRef < 'tcx >) -> bool { self . local == other . local && self . projection . len () <= other . projection . len () && self . projection == & other . projection [.. self . projection . len ()] } } pub (super) struct Prefixes < 'tcx > { kind : PrefixSet , next : Option < PlaceRef < 'tcx > > , } #[derive (Copy , Clone , PartialEq , Eq , Debug)] pub (super) enum PrefixSet { #[doc = " Doesn't stop until it returns the base case (a Local or"] #[doc = " Static prefix)."] All , #[doc = " Stops at any dereference."] Shallow , } impl < 'tcx > MirBorrowckCtxt < '_ , '_ , 'tcx > { #[doc = " Returns an iterator over the prefixes of `place`"] #[doc = " (inclusive) from longest to smallest, potentially"] #[doc = " terminating the iteration early based on `kind`."] pub (super) fn prefixes (& self , place_ref : PlaceRef < 'tcx > , kind : PrefixSet) -> Prefixes < 'tcx > { Prefixes { next : Some (place_ref) , kind } } } impl < 'tcx > Iterator for Prefixes < 'tcx > { type Item = PlaceRef < 'tcx > ; fn next (& mut self) -> Option < Self :: Item > { let mut cursor = self . next ? ; loop { match cursor . last_projection () { None => { self . next = None ; return Some (cursor) ; } Some ((cursor_base , elem)) => { match elem { ProjectionElem :: Field (_ , _) => { self . next = Some (cursor_base) ; return Some (cursor) ; } ProjectionElem :: UnwrapUnsafeBinder (_) => { self . next = Some (cursor_base) ; return Some (cursor) ; } ProjectionElem :: Downcast (..) | ProjectionElem :: Subslice { .. } | ProjectionElem :: OpaqueCast { .. } | ProjectionElem :: ConstantIndex { .. } | ProjectionElem :: Index (_) => { cursor = cursor_base ; } ProjectionElem :: Subtype (..) => { panic ! ("Subtype projection is not allowed before borrow check") } ProjectionElem :: Deref => { match self . kind { PrefixSet :: Shallow => { self . next = None ; return Some (cursor) ; } PrefixSet :: All => { self . next = Some (cursor_base) ; return Some (cursor) ; } } } } } } } } }